<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Platform ayarları</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:750px;margin:35px auto;padding:0 18px}.panel{background:white;padding:24px;border-radius:14px}label{display:block;font-size:14px;font-weight:700;margin:16px 0}input{display:block;width:100%;box-sizing:border-box;padding:12px;border:1px solid #dfe6e0;border-radius:8px;margin-top:7px;font:inherit}button{background:#176b50;color:white;border:0;border-radius:8px;padding:13px 18px;font-weight:700}.note{background:#fff6e7;color:#76551c;padding:12px;border-radius:9px;font-size:13px}</style></head><body><main class="wrap"><h1>Platform ayarları</h1><section class="panel"><form method="post" action="/admin/settings"><?= csrf_field() ?><label>Varsayılan platform komisyonu (%)<input type="number" name="commission" min="0" max="50" step=".1" value="<?= e($settings['platform.commission_percent']??'12') ?>"></label><label>Varsayılan para birimi (ISO kodu)<input name="currency" maxlength="3" pattern="[A-Za-z]{3}" value="<?= e($settings['app.currency']??'TRY') ?>"></label><label>Zaman dilimi<input name="timezone" value="<?= e($settings['app.timezone']??'Europe/Istanbul') ?>"></label><p class="note">Ödeme altyapısı henüz etkinleştirilmedi. Gerçek kart tahsilatı bu sürümde kapalıdır.</p><button type="submit">Ayarları kaydet</button></form></section><p><a href="/admin">Yönetim paneli</a></p></main></body></html>